import {readFileSync, writeFileSync} from 'node:fs';
import {sources, people, weeks, questions, cases} from './content.mjs';
import {categories, readings, related, routes, fieldnotes, enrich} from './library.mjs';
import {stories, enrichStories} from './stories.mjs';
import explanations from './chapters.mjs';
import {jobsBrief} from './jobs-brief.mjs';
import {analyticsBlock} from './analytics/build-analytics.mjs';
enrich(sources,people,weeks,questions,cases);
enrichStories(sources,readings,weeks);

const escape = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const byId = Object.fromEntries(sources.map(source=>[source.id,source]));
const link = (id, title) => { const source=byId[id]; return `<a href="${escape(source.url)}" target="_blank" rel="noopener noreferrer">${escape(title || source.title)} <span aria-hidden="true">↗</span></a>`; };
const refs = ids => `<div class="references">${ids.map(id=>link(id)).join('<span aria-hidden="true"> · </span>')}</div>`;
const heading = (number,title,description) => `<div class="section-heading"><h2 tabindex="-1">${title}</h2><p>${description}</p></div>`;
const storyCards = stories.map(story=>`<article class="row story" id="story-${story.id}" data-kind="Story" data-category="${story.category}"><p class="eyebrow">${story.category}, ${story.kind.toLowerCase()}</p><h3>${story.title}</h3><p class="row-meta">${story.person}, ${story.company}</p><p class="row-summary">${story.journey}</p><details><summary>Story notes</summary><dl><dt>What happened</dt><dd>${story.account}</dd><dt>The tradeoff</dt><dd>${story.tension}</dd><dt>What to take forward</dt><dd>${story.focus}</dd><dt>Reflect on</dt><dd>${story.question}</dd></dl><p>Read the original: ${link(story.source)} <span class="subtle">(${escape(byId[story.source].date)})</span></p><p class="subtle">${story.boundary}</p><p class="related">Related reading ${story.related.map(id=>link(id)).join('')}</p><p class="status">Source content checked ${byId[story.source].reviewed}. Personal claims are attributed, not independently verified.</p></details></article>`).join('');

// Job openings: snapshot from work/fetch-jobs.mjs (public Greenhouse, Lever, and Ashby boards).
const jobData = JSON.parse(readFileSync(new URL('../docs/JOBS.json',import.meta.url),'utf8'));
const jobDate = new Date(jobData.checkedAt).toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric',timeZone:'UTC'});
const jobFamily = title => /\bintern\b|internship|new grad|university|year at palantir/i.test(title)?'Internship & early career':/\b(head|director|vp|vice president)\b|engineering manager|manager,? forward|forward deployed (engineering )?manager|\blead\b(?!.*engineer)/i.test(title)&&!/product manager/i.test(title)?'Leadership':/strategist|product manager|banker|engagement|program manager|growth|account|deployment lead/i.test(title)?'Strategy & product':'Engineering';
const jobFamilies = ['Engineering','Strategy & product','Leadership','Internship & early career'];
const jobRegionRules = [
 ['United States',/United States|\bUSA?\b|U\.S\.|New York|NYC|San Francisco|\bSF\b|Bay Area|Seattle|Austin|Boston|Washington|D\.C\.|\bDC\b|Chicago|Los Angeles|Palo Alto|Mountain View|Sunnyvale|San Jose|San Mateo|San Diego|Menlo Park|Atlanta|Dallas|Houston|Denver|Miami|Philadelphia|Phoenix|Honolulu|Brooklyn|Costa Mesa|Huntington Beach|Raleigh|Charlotte|Nashville|Salt Lake|Fayetteville|Kitsap|Laurel|Norfolk|Columbus|Berkeley|Minneapolis|Minnesota|California|Texas|Virginia|Maryland|Florida|Georgia|Idaho|Colorado|Massachusetts|Pennsylvania|New Jersey|Illinois|Ohio|Alabama|Connecticut|Delaware|Indiana|Missouri|Arizona|Carolina|New Hampshire|Rhode Island|West Coast|Northeast|Southeast|Central - United|USCA|, [A-Z]{2}\b/],
 ['Canada',/Canada|Toronto|Vancouver|Montreal|Ottawa|North America/i],
 ['Europe & UK',/London|United Kingdom|\bUK\b|England|Edinburgh|Ireland|Dublin|Cork|Paris|France|Germany|Berlin|Munich|Frankfurt|Amsterdam|Netherlands|Madrid|Spain|Stockholm|Sweden|Z[uü]rich|Switzerland|Europe|Brussels|Belgium|Serbia|Belgrade|Bulgaria|Sofia|Bosnia|Norway|Oslo|Estonia|Latvia|Slovenia|Hungary|Portugal|Poland|Warsaw|Austria|Finland|Montenegro|Albania|Lithuania|Vilnius|Slovakia|Denmark|Czech|Croatia|Greece|Italy|Romania|Bucharest|EMEA/i],
 ['Asia-Pacific',/Singapore|Tokyo|Japan|Seoul|Korea|Sydney|Melbourne|Australia|India|Bengaluru|Bangalore|Mumbai|Delhi|Gurugram|Hyderabad|Taiwan|Asia|APAC|Hong Kong/i],
 ['Middle East',/Middle East|Dubai|Abu Dhabi|UAE|United Arab Emirates|Saudi|Riyadh|Doha|Qatar|Israel|Tel Aviv/i],
 ['Latin America',/Argentina|Mexico|Brazil|S[aã]o Paulo|Chile|Colombia|Latin America|LATAM/i],
];
const jobRegions = job => {const found=jobRegionRules.filter(([,rule])=>rule.test(job.location)).map(([name])=>name);if(job.remote||/remote/i.test(job.location))found.push('Remote');return found.length?found:['Unspecified'];};
const boardUrl = job => ({greenhouse:'https://job-boards.greenhouse.io/',lever:'https://jobs.lever.co/',ashby:'https://jobs.ashbyhq.com/'})[job.ats]+job.board;
const atsName = {greenhouse:'Greenhouse',lever:'Lever',ashby:'Ashby'};
const jobCompanies = Object.values(jobData.jobs.reduce((groups,job)=>{(groups[job.company]??={company:job.company,board:boardUrl(job),ats:job.ats,jobs:[]}).jobs.push(job);return groups;},{})).sort((a,b)=>b.jobs.length-a.jobs.length||a.company.localeCompare(b.company));
const jobRegionList = [...jobRegionRules.map(([name])=>name),'Remote','Unspecified'];
const jobCards = jobCompanies.map(group=>{
 const roles=Object.values(group.jobs.reduce((titles,job)=>{(titles[job.title]??={title:job.title,family:jobFamily(job.title),postings:[]}).postings.push(job);return titles;},{})).sort((a,b)=>jobFamilies.indexOf(a.family)-jobFamilies.indexOf(b.family)||b.postings.length-a.postings.length||a.title.localeCompare(b.title));
 const families=[...new Set(roles.map(role=>role.family))];
 return `<article class="row item job-company" id="company-${String(group.company).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}" data-item="jobs" data-kind="Hiring company" data-families="${escape(families.join('|'))}"><div class="job-head"><div><h3>${escape(group.company)}</h3><p class="row-meta">${group.jobs.length} open ${group.jobs.length===1?'posting':'postings'}</p></div><a class="all-jobs" href="${escape(group.board)}" target="_blank" rel="noopener noreferrer">All ${escape(group.company)} jobs</a></div><ul class="job-roles">${roles.map(role=>{const latest=role.postings.map(job=>job.posted).filter(Boolean).sort().pop();const pay=role.postings.find(job=>job.compensation)?.compensation;return `<li data-job data-family="${escape(role.family)}"><div class="job-title"><strong>${escape(role.title)}</strong><span class="job-family">${escape(role.family)}${latest?`, posted ${latest}`:''}</span></div>${pay?`<p class="job-pay">${escape(pay)}</p>`:''}<div class="job-locations">${role.postings.map(job=>`<a href="${escape(job.url)}" target="_blank" rel="noopener noreferrer" data-regions="${escape(jobRegions(job).join('|'))}">${escape(job.location||'Location not listed')}${job.remote&&!/remote/i.test(job.location)?', remote':''}</a>`).join('')}</div></li>`;}).join('')}</ul></article>`;
}).join('');
const stages = [
['Discover the work behind the request.','Start with a person, a recurring task, and an observable problem. Watch how work happens today.','Example: a support team asks for a chatbot. First establish which customer tasks fail and why.','A validated problem brief','Name the user, workflow, baseline, sponsor, and constraint. Make the cost of the current problem visible.','Observe the customer’s workflow and earn enough context to challenge the initial request.','Find a consequential problem between teams. Establish who can authorize a change and who will operate it.'],
['Frame a bounded, valuable intervention.','Convert an ambiguous ambition into a small decision you can test.','Example: choose one support issue with accessible data and an agreed definition of successful resolution.','A scoped pilot proposal','Specify the target cohort, acceptance criteria, dependencies, deadline, and stop condition.','Negotiate scope with the customer and align the pilot with the product’s actual capabilities.','Compare candidate projects and explain why this opportunity deserves attention now.'],
['Build the full path to an outcome.','Connect the interface, data, business logic, and feedback in one usable slice.','Example: an agent retrieves the right policy, checks eligibility, and proposes a resolution for review.','A working slice and an eval set','Show one complete user flow. Test representative failures before expanding features.','Make the integration work within the customer’s real permissions and operating constraints.','Create a useful first version, then test the assumptions that justified the project.'],
['Deploy into an owned workflow.','A release needs users, monitoring, support, and a way to recover.','Example: launch to a small eligible cohort with clear escalation and rollback criteria.','An operated pilot','A named owner can detect failures, respond, and explain the system’s limits.','Train customer operators and make the handoff part of delivery.','Resolve cross-team ownership and ensure the project survives beyond its original builder.'],
['Measure the change that matters.','Connect use and quality to the user’s outcome, including the cost of review and support.','Example: compare successful resolutions and repeat contacts for similar work, not just chat volume.','An impact review','State the denominator, measurement window, comparison, costs, and uncertainty.','Review customer outcomes and use the evidence to decide whether to expand.','Revisit the original business case and decide whether to continue, change direction, or stop.'],
['Scale what you have learned.','Turn repeated needs into reusable capabilities, while retaining an accountable operator.','Example: move common integrations and evals into a maintained package with customer-specific configuration.','A reusable capability and handoff','Show what becomes easier for the next customer or team, and measure that change.','Bring repeated field problems to product and reduce the next deployment’s effort.','Decide whether the solution should become a product, shared platform, or well-maintained local tool.']
];

const roman=['I','II','III','IV','V','VI','VII'];
const tagFor=id=>{const type=byId[id].type;return type==='Video'||type==='Talk companion'?'Video':type==='Podcast'?'Podcast':/^Book/.test(type)?'Book':type==='Paper'?'Paper':'';};
const readingById=Object.fromEntries(readings.map(reading=>[reading.id,reading]));
// In chapters, a reading also says what to focus on and how to apply it.
const readItem=(id,detailed)=>{const reading=detailed&&readingById[id];return `<li>${link(id)}${tagFor(id)?` <span class="tag">${tagFor(id)}</span>`:''}${byId[id].why?`<span class="why">${escape(byId[id].why)}</span>`:''}${reading?`<span class="how"><strong>Focus:</strong> ${reading.focus} <strong>Apply:</strong> ${reading.outcome}</span>`:''}</li>`;};
const readList=(ids,detailed)=>`<ul class="readlist">${[...new Set(ids)].map(id=>readItem(id,detailed)).join('')}</ul>`;
const phases=['Discover','Frame','Build','Deploy','Measure','Scale'];
const parts=[...phases.map((phase,index)=>({id:'part-'+(index+1),label:'Part '+roman[index],title:phase,intro:stages[index][1],example:stages[index][2],chapters:weeks.filter(week=>week.phase===phase).map(week=>({id:'ch-'+week.id,number:week.id,title:week.title,week}))})),
 {id:'part-7',label:'Part VII',title:'Advanced fieldcraft',intro:'For engineers already delivering in the field. Each chapter is one hard decision: what to inspect, what to decide, and what evidence to bring to a review. Bring a current project.',example:'',chapters:fieldnotes.map((note,index)=>({id:'ch-'+(13+index),number:13+index,title:note.title,note}))}];
const chapterCount=parts.reduce((sum,part)=>sum+part.chapters.length,0);
const prose=text=>text.replace(/\{([\w-]+)\|([^}]+)\}/g,(match,id,anchor)=>{if(!byId[id])throw new Error('Unknown source '+id);return link(id,anchor);});
const explainBlock=number=>{const entry=explanations[number];if(!entry)throw new Error('Missing explanation for chapter '+number);return `<div class="explain"><h4>How it works</h4>${entry.explain.map(text=>`<p>${prose(text)}</p>`).join('')}<h4>Worked example</h4><div class="example">${entry.example.map(text=>`<p>${prose(text)}</p>`).join('')}</div></div>`;};
const chapterBody=chapter=>{if(chapter.week){const week=chapter.week;return `<p class="lead">${week.objective}</p>${explainBlock(chapter.number)}<h4>Read</h4>${readList([...week.refs,...week.deeper],true)}<h4>Do</h4><ul class="tasks">${week.tasks.map(task=>`<li>${escape(task)}</li>`).join('')}</ul><p class="done"><strong>You are done when:</strong> ${week.gate}</p>`;}const note=chapter.note;return `<p class="lead">${note.scenario}</p>${explainBlock(chapter.number)}<h4>Inspect</h4><p>${note.inspect}</p><h4>Decide</h4><p>${note.decision}</p><h4>Bring to a review</h4><p>${note.artifact}</p><p class="done"><strong>Common trap:</strong> ${note.trap}</p><h4>Read</h4>${readList(note.refs,true)}`;};
const toc=`<nav class="toc" aria-label="Contents"><ol class="toc-parts"><li><a href="#preface">Preface: what the job is</a></li>${parts.map(part=>`<li><a class="toc-part" href="#${part.id}">${part.label}. ${part.title}</a><ol>${part.chapters.map(chapter=>`<li value="${chapter.number}"><a href="#${chapter.id}">${escape(chapter.title)}</a></li>`).join('')}</ol></li>`).join('')}</ol></nav>`;
const preface=`<article class="chapter" id="preface" data-kind="Preface" data-chapter="0" data-part="Preface"><p class="ch-no">Preface</p><h3>What the job is</h3><p class="lead">A Forward Deployed Engineer takes software from a promising demo to a system that real users depend on, inside a customer’s data, workflows, and constraints. A Special Projects Engineer owns an unclear, high-stakes problem from start to finish, often across team boundaries.</p><p>Both roles need the same craft: engineering that holds up in production, enough domain knowledge to challenge the original request, and evidence that the work changed an outcome. Titles vary by company, and neither role is a seniority level.</p><h4>How to use this book</h4><p>Read the chapters in order with one real project beside you: a bounded, permitted workflow with real users. If you lack user access, use public or synthetic data and label the result as a simulation. Each chapter ends with a test for when you are done. Plan for five to eight focused hours a week.</p><h4>How others teach this</h4><p>Training programs pair technical work with customer work. The ${link('academy-method','FDE Academy method')} runs parallel technical and consulting tracks with a reviewed portfolio; it is a provider’s description of itself, and this guide is unaffiliated with it. ${link('plank-about','Plank')} describes a training-and-embedded-team model; its handoff lesson appears in chapter 11.</p><h4>The engagement, phase by phase</h4><ol class="phase-list">${phases.map((phase,index)=>`<li><strong>${phase}.</strong> ${stages[index][1]} <a href="#part-${index+1}">Part ${roman[index]}</a></li>`).join('')}</ol><h4>Read</h4>${readList(['openai-fde','nick','ramp'])}</article>`;
const book=parts.map(part=>`<div class="part" id="${part.id}"><p class="part-no">${part.label}</p><h3 class="part-title" data-kind="Part">${part.title}</h3><p>${part.intro}</p>${part.example?`<p class="subtle">${part.example}</p>`:''}</div>${part.chapters.map(chapter=>`<article class="chapter" id="${chapter.id}" data-kind="Chapter" data-chapter="${chapter.number}" data-part="${escape(part.title)}"><p class="ch-no">Chapter ${chapter.number}</p><h3>${escape(chapter.title)}</h3>${chapterBody(chapter)}</article>`).join('')}`).join('');

const citedIn={};parts.forEach(part=>part.chapters.forEach(chapter=>(chapter.week?[...chapter.week.refs,...chapter.week.deeper]:chapter.note.refs).forEach(id=>(citedIn[id]??=[]).push(chapter))));
const citedLinks=id=>citedIn[id]?`<p class="cited">Used in ${citedIn[id].map(chapter=>`<a href="#${chapter.id}">chapter ${chapter.number}: ${escape(chapter.title)}</a>`).join(', ')}</p>`:'';
const readingRow=reading=>{const source=byId[reading.id];return `<article class="row" id="reading-${reading.id}" data-kind="${reading.format}"><p class="eyebrow">${categories.find(category=>category.id===reading.category).title}, ${reading.level.toLowerCase()}</p><h3>${link(reading.id)}</h3><p class="row-meta">${escape(source.author)}, ${escape(source.date)}. ${reading.access}</p><p class="row-summary">${reading.why}</p>${citedLinks(reading.id)}<details><summary>How to use it</summary><dl><dt>Focus your reading</dt><dd>${reading.focus}</dd><dt>Put it to work</dt><dd>${reading.outcome}</dd><dt>Before you start</dt><dd>${reading.caveat}</dd></dl><p class="status">${escape(source.status)}. Reviewed ${source.reviewed}</p></details></article>`;};
const readingIds=new Set(readings.map(reading=>reading.id));
const extraVideos=sources.filter(source=>source.type==='Video'&&!readingIds.has(source.id));
const resourceGroups=[
 ['res-books','Books',readings.filter(reading=>/^Book/.test(reading.format)).map(readingRow).join('')],
 ['res-articles','Articles and guides',readings.filter(reading=>['Article','Documentation','Paper','Repository','Hands-on lesson'].includes(reading.format)).map(readingRow).join('')],
 ['res-podcasts','Podcasts',readings.filter(reading=>reading.format==='Podcast').map(readingRow).join('')],
 ['res-videos','Videos and talks',readings.filter(reading=>/talk/i.test(reading.format)).map(readingRow).join('')+extraVideos.map(source=>`<article class="row" id="video-${source.id}" data-kind="Video"><h3>${link(source.id)}</h3><p class="row-meta">${escape(source.author)}, ${escape(source.date)}</p>${source.why?`<p class="row-summary">${escape(source.why)}</p>`:''}</article>`).join('')]];
const none='<span class="subtle">None yet</span>';
const peopleRows=`<div class="table-scroll"><table class="people"><thead><tr><th scope="col">Person</th><th scope="col">Why follow</th><th scope="col">X</th><th scope="col">Read</th><th scope="col">Watch or listen</th></tr></thead><tbody>${people.map(person=>`<tr id="person-${String(person.name).toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}" data-kind="Person"><th scope="row" data-label="Person"><strong>${escape(person.name)}</strong><span>${escape(person.role)}, ${escape(person.company)}</span></th><td data-label="Why follow">${escape(person.why)}</td><td data-label="X">${person.handle?`<a href="https://x.com/${escape(person.handle)}" target="_blank" rel="noopener noreferrer">@${escape(person.handle)}</a>${person.handle==='nabeelqu'?'':'<span class="unverified">unverified</span>'}`:none}</td><td data-label="Read">${person.article?link(person.article):none}</td><td data-label="Watch or listen">${person.talk?link(person.talk):none}</td></tr>`).join('')}</tbody></table></div>`;
const subnav=items=>`<div class="tabs" role="tablist" aria-label="Sections">${items.map(([id,label],index)=>`<a role="tab" id="tab-${id}" data-tab="${id}" href="#${id}" aria-controls="${id}" aria-selected="${index===0}">${label}</a>`).join('')}</div>`;
const questionRow=question=>`<article class="row" id="question-${question.id}" data-kind="Interview question" data-category="${question.evidence}"><p class="eyebrow">${question.id}, ${question.company}, ${question.topic}</p><h3 class="question">${escape(question.prompt)}</h3><p class="row-meta">${question.evidence}. Source: ${link(question.source)}</p><details><summary>Response guide</summary><p>${escape(question.context)}</p><p>${escape(question.guide)}</p><p><strong>Follow-up to expect:</strong> ${escape(question.followup)}</p></details></article>`;
const questionGroups=[['questions','Candidate reports','Interview questions from candidate reports',question=>question.id<='Q06','Paraphrased from first-person candidate reports. Reports are uncorroborated and process details vary; the Palantir posts are limited, concentrated evidence. Ask your recruiter about the current format and AI-tool rules.'],['q-employer','Employer formats','Interview formats published by employers',question=>question.id>='Q07'&&question.id<='Q08','Summaries of an interview format the employer published itself. The format is documented; the exact prompts you get will differ.'],['q-practice','Practice questions','Practice questions from real cases',question=>question.id>='Q09','Original questions, not reported employer questions. Q09–Q15 are derived from documented cases or architecture; Q16 applies an operations framework to a hypothetical scenario.']];
const questionRows=questionGroups.map(([id,tab,title,match,intro])=>`<section class="group" id="${id}" role="tabpanel" aria-labelledby="tab-${id}"><h2 class="group-title">${title}</h2><p class="group-intro">${intro} Answer aloud and state your assumptions before you open the guide; guides are editorial suggestions, not official answer keys.</p><div class="list">${questions.filter(match).map(questionRow).join('')}</div></section>`).join('');
const caseRows=cases.map(item=>`<article class="row" id="case-${item.id}" data-kind="Case study" data-category="${item.theme}"><p class="eyebrow">${item.theme}</p><h3>${item.title}</h3><p class="row-summary">${item.problem}</p><p class="row-meta">${link(item.source)}</p><details><summary>Approach and result</summary><dl><dt>Approach</dt><dd>${item.approach}</dd><dt>Reported result</dt><dd>${item.result}</dd><dt>Evidence limit</dt><dd>${item.limit}</dd><dt>Discuss</dt><dd>${item.question} Identify the user, baseline, intervention, measurement window, ongoing cost, and evidence you would need before repeating the claim.</dd></dl></details></article>`).join('');

// Stats page: an Amplitude dashboard embed. Paste the embed code or its src URL into work/stats.json.
const statsConfig=JSON.parse(readFileSync(new URL('./stats.json',import.meta.url),'utf8'));
const amplitudeUrl=value=>{const raw=String(value||'').trim();const src=(raw.match(/src=["']([^"']+)["']/)||[,raw])[1];try{const url=new URL(src);return url.protocol==='https:'&&/(^|\.)amplitude\.com$/.test(url.hostname)?url.href:'';}catch{return '';}};
const statsEmbed=amplitudeUrl(process.env.STATS_EMBED||statsConfig.embed);
const statsLink=amplitudeUrl(statsConfig.publicLink);
const statsIcon='<svg aria-hidden="true" width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round"><path d="M3 17h14"/><path d="M5.5 13.5v-4"/><path d="M10 13.5v-9"/><path d="M14.5 13.5v-6"/></svg>';

const compareTable=`<div class="table-scroll"><table class="compare"><thead><tr><th scope="col"><span class="sr-only">Aspect</span></th><th scope="col">Forward Deployed Engineer</th><th scope="col">Special Projects Engineer</th></tr></thead><tbody><tr><th scope="row">The job</th><td>Own the deployment. Make a product work inside one customer’s data, workflows, and constraints.</td><td>Own the unclear problem. Take a consequential problem nobody owns and carry it to a result.</td></tr><tr><th scope="row">Where you work</th><td>With the customer: their systems, their users, their stakeholders.</td><td>Inside the company, across team boundaries: infrastructure, operations, new products.</td></tr>${phases.map((phase,index)=>`<tr><th scope="row">${phase}</th><td>${stages[index][5]}</td><td>${stages[index][6]}</td></tr>`).join('')}<tr><th scope="row">Read</th><td>${link('openai-fde')}<br>${link('ramp')}</td><td>${link('nick')}</td></tr></tbody></table></div>`;
const hiringCounts=Object.entries(jobData.jobs.reduce((counts,job)=>(counts[job.company]=(counts[job.company]||0)+1,counts),{})).sort((a,b)=>b[1]-a[1]);
const topHirers=hiringCounts.slice(0,6).map(([company,count])=>`${escape(company)} (${count})`).join(', ');
const fdeAnswer=`A forward deployed engineer (FDE) is a software engineer who works directly with a customer to make a product deliver a real outcome inside that customer’s systems, data, and workflows. FDEs write and ship production code, and they bring problems that repeat across customers back to the product team. Palantir popularized the role; many AI and data companies now hire for it.`;
const faqs=[
 ['What is a forward deployed engineer?',`${fdeAnswer} <a href="#what-is-fde">Read the full answer</a>.`],
 ['How is an FDE different from a Special Projects Engineer (SPE)?','An FDE owns a deployment for one customer: discovery, integration, production delivery, and adoption. An SPE owns an unclear, high-stakes problem inside the company, often across team boundaries. Both need the same craft; they point it at different problems. <a href="#fde-vs-spe">See the comparison</a>.'],
 ['How do I become a forward deployed engineer?',`Learn the work in the order an engagement runs: discover the real problem, frame a bounded change, build a thin working slice, deploy it into an owned workflow, measure the outcome, then make it reusable. The free <a href="#learn">${chapterCount}-chapter guide</a> follows those phases, with reading, tasks, and a test for when you are done with each chapter.`],
 ['What do forward deployed engineer interviews look like?',`Reported FDE loops mix a product decomposition or system-design prompt, a coding exercise, and questions about working with customers. Palantir candidates report decomposition and coding rounds; Sierra publishes a plan, build, and review format. The <a href="#questions">${questions.length} interview questions</a> each name their source and say whether they are reported, published, or editorial.`],
 ['Which companies hire forward deployed engineers?',`In the ${jobDate} snapshot of public job boards, ${jobCompanies.length} companies had ${jobData.jobs.length} open FDE-type postings. The most were at ${topHirers}. The <a href="#jobs">jobs list</a> links each posting on the employer’s own site.`],
 ['Is FDE Academy free, and who runs it?','Yes. It is free, open source, and needs no account. It is an independent, AI-assisted guide that links every resource to its original source and is not affiliated with the companies it cites. <a href="#about">How the guide is made</a>.'],
];
const faqBlock=`<section class="home-block faq" id="faq" aria-labelledby="faqTitle"><h2 id="faqTitle">Questions people ask</h2><div class="faq-list">${faqs.map(([question,answer])=>`<details class="faq-item"><summary>${question}</summary><p>${answer}</p></details>`).join('')}</div></section>`;
const answerPanels=`<section id="what-is-fde" class="panel">${heading('','What is a forward deployed engineer?','')}<div class="answer"><p class="answer-lead">${fdeAnswer}</p>
<h3>What FDEs do, phase by phase</h3><ol class="phase-list">${phases.map((phase,index)=>`<li><strong>${phase}.</strong> ${stages[index][5]}</li>`).join('')}</ol>
<h3>Where the role came from</h3><p>Palantir embedded engineers at customer sites to make its platforms work on real problems and to find what the product was missing. Former Palantir FDE Nabeel Qureshi describes the work in ${link('nabeel','Reflections on Palantir')}, and Bob McGrew explains why AI startups adopted the model in ${link('pod-fde-playbook','the FDE playbook episode')}.</p>
<h3>Who hires FDEs now</h3><p>In the ${jobDate} snapshot, ${jobCompanies.length} companies had ${jobData.jobs.length} open FDE-type postings. The most were at ${topHirers}. <a href="#jobs">See every open role</a>.</p>
<h3>How it differs from a Special Projects Engineer</h3><p>An FDE owns one customer’s deployment; an SPE owns an unclear problem inside the company. <a href="#fde-vs-spe">Compare the two roles</a>.</p>
<h3>Read next</h3>${readList(['openai-fde','ramp','nabeel','pod-lenny-palantir','pod-fde-playbook'])}<p class="next-step"><a class="button primary" href="#learn">Start the guide</a></p></div></section>
<section id="fde-vs-spe" class="panel">${heading('','FDE vs SPE: what is the difference?','')}<div class="answer"><p class="answer-lead">A Forward Deployed Engineer (FDE) owns a deployment for one customer and makes the product work inside that customer’s data and workflows. A Special Projects Engineer (SPE) owns an unclear, consequential problem inside the company and carries it across team boundaries to a result. The craft is shared; the problem is different.</p>${compareTable}
<h3>Read about each role</h3><p><strong>FDE</strong></p>${readList(['openai-fde','ramp','pod-ramp-services'])}<p><strong>SPE</strong></p>${readList(['nick'])}<p class="subtle">Titles vary by company, and neither role is a seniority level. This comparison is editorial.</p></div></section>
<section id="about" class="panel">${heading('','About FDE Academy','')}<div class="answer"><p class="answer-lead">FDE Academy is a free, open-source field guide for engineers who want to do forward deployed work. It is independent and not affiliated with the companies, programs, or authors it cites.</p>
<h3>How the content is chosen</h3><p>Every resource links to a specific publication, not a homepage. Each entry says why it is worth your time, what to focus on, how to apply it, and its limits. Claims are labeled as reported by a source, verified, or editorial judgment, and each source shows the date it was last checked.</p>
<h3>How it is made</h3><p>The guide is AI-assisted: research, drafting, and checks are done with AI tools and reviewed by the maintainer. Interview questions name their source and evidence type. The jobs list is an automated snapshot of public Greenhouse, Lever, and Ashby job boards, dated ${jobDate}.</p>
<h3>Who maintains it</h3><p>FDE Academy is maintained by Jiabin (Louis) Lu, an engineer and go-to-market lead, who also runs <a href="https://gtm-pod.com/fde" target="_blank" rel="noopener">gtmpod</a>, an independent review of AI tools for go-to-market teams with a hub for forward deployed engineers.</p>
<h3>Corrections and contributions</h3><p>Found a wrong claim, a dead link, or a better source? <a href="https://github.com/LouisLu888/open-fde/issues" target="_blank" rel="noopener noreferrer">Open an issue</a> or a pull request on <a href="https://github.com/LouisLu888/open-fde" target="_blank" rel="noopener noreferrer">GitHub</a>.</p>
<h3>Privacy</h3><p>No account and nothing stored in your browser. On open-fde.ai, anonymous usage analytics and session recordings, with anything typed hidden, help improve the guide. Do Not Track and Global Privacy Control turn them off.</p></div></section>`;
